1	/** @import { AST } from 'svelte/compiler' */
2	
3	import { existsSync } from 'node:fs';
4	import * as path from 'node:path';
5	
6	import MagicString from 'magic-string';
7	import sharp from 'sharp';
8	import { parse } from 'svelte-parse-markup';
9	import { walk } from 'zimmerframe';
10	
11	// TODO: expose this in vite-imagetools rather than duplicating it
12	const OPTIMIZABLE = /^[^?]+\.(avif|heif|gif|jpeg|jpg|png|tiff|webp)(\?.*)?$/;
13	
14	/**
15	 * @param {{
16	 *   plugin_context: import('vite').Rollup.PluginContext
17	 *   vite_config: import('vite').ResolvedConfig
18	 *   imagetools_plugin: import('vite').Plugin
19	 * }} opts
20	 * @returns {import('svelte/types/compiler/preprocess').PreprocessorGroup}
21	 */
22	export function image(opts) {
23		// TODO: clear this map in dev mode to avoid memory leak
24		/**
25		 * URL to image details
26		 * @type {Map<string, import('vite-imagetools').Picture>}
27		 */
28		const images = new Map();
29	
30		return {
31			async markup({ content, filename }) {
32				if (!content.includes('<enhanced:img')) {
33					return;
34				}
35	
36				const s = new MagicString(content);
37				const ast = parse(content, { filename, modern: true });
38	
39				/**
40				 * Import path to import name
41				 * e.g. ./foo.png => __IMPORTED_ASSET_0__
42				 * @type {Map<string, string>}
43				 */
44				const imports = new Map();
45	
46				/**
47				 * @param {import('svelte/compiler').AST.RegularElement} node
48				 * @param {AST.Text | AST.ExpressionTag} src_attribute
49				 * @returns {Promise<void>}
50				 */
51				async function update_element(node, src_attribute) {
52					if (src_attribute.type === 'ExpressionTag') {
53						const start =
54							'end' in src_attribute.expression
55								? src_attribute.expression.end
56								: src_attribute.expression.range?.[0];
57						const end =
58							'start' in src_attribute.expression
59								? src_attribute.expression.start
60								: src_attribute.expression.range?.[1];
61	
62						if (typeof start !== 'number' || typeof end !== 'number') {
63							throw new Error('ExpressionTag has no range');
64						}
65						const src_var_name = content.substring(start, end).trim();
66	
67						s.update(node.start, node.end, dynamic_img_to_picture(content, node, src_var_name));
68						return;
69					}
70	
71					const original_url = src_attribute.raw.trim();
72					let url = original_url;
73	
74					if (OPTIMIZABLE.test(url)) {
75						const sizes = get_attr_value(node, 'sizes');
76						const width = get_attr_value(node, 'width');
77						url += url.includes('?') ? '&' : '?';
78						if (sizes && 'raw' in sizes) {
79							url += 'imgSizes=' + encodeURIComponent(sizes.raw) + '&';
80						}
81						if (width && 'raw' in width) {
82							url += 'imgWidth=' + encodeURIComponent(width.raw) + '&';
83						}
84						url += 'enhanced';
85					}
86	
87					// resolves the import so that we can build the entire picture template string and don't
88					// need any logic blocks
89					const resolved_id = (await opts.plugin_context.resolve(url, filename))?.id;
90					if (!resolved_id) {
91						const query_index = url.indexOf('?');
92						const file_path = query_index >= 0 ? url.substring(0, query_index) : url;
93						if (existsSync(path.resolve(opts.vite_config.publicDir, file_path))) {
94							throw new Error(
95								`Could not locate ${file_path}. Please move it to be located relative to the page in the routes directory or reference it beginning with /static/. See https://vitejs.dev/guide/assets for more details on referencing assets.`
96							);
97						}
98						throw new Error(
99							`Could not locate ${file_path}. See https://vitejs.dev/guide/assets for more details on referencing assets.`
100						);
101					}
102	
103					if (OPTIMIZABLE.test(url)) {
104						let image = images.get(resolved_id);
105						if (!image) {
106							image = await process(resolved_id, opts);
107							images.set(resolved_id, image);
108						}
109						s.update(node.start, node.end, img_to_picture(content, node, image));
110					} else {
111						const metadata = await sharp(resolved_id).metadata();
112						// this must come after the await so that we don't hand off processing between getting
113						// the imports.size and incrementing the imports.size
114						const name = imports.get(original_url) || '__IMPORTED_ASSET_' + imports.size + '__';
115						const new_markup = `<img ${serialize_img_attributes(content, node.attributes, {
116							src: `{${name}}`,
117							width: metadata.width || 0,
118							height: metadata.height || 0
119						})} />`;
120						s.update(node.start, node.end, new_markup);
121						imports.set(original_url, name);
122					}
123				}
124	
125				/**
126				 * @type {Array<ReturnType<typeof update_element>>}
127				 */
128				const pending_ast_updates = [];
129	
130				walk(/** @type {import('svelte/compiler').AST.TemplateNode} */ (ast), null, {
131					RegularElement(node, { next }) {
132						if ('name' in node && node.name === 'enhanced:img') {
133							// Compare node tag match
134							const src = get_attr_value(node, 'src');
135	
136							if (!src || typeof src === 'boolean') return;
137	
138							pending_ast_updates.push(update_element(node, src));
139	
140							return;
141						}
142	
143						next();
144					}
145				});
146	
147				await Promise.all(pending_ast_updates);
148	
149				// add imports
150				let text = '';
151				if (imports.size) {
152					for (const [path, import_name] of imports.entries()) {
153						text += `\timport ${import_name} from "${path}";\n`;
154					}
155				}
156	
157				if (ast.instance) {
158					// @ts-ignore
159					s.appendLeft(ast.instance.content.start, text);
160				} else {
161					s.prepend(`<script>${text}</script>\n`);
162				}
163	
164				return {
165					code: s.toString(),
166					map: s.generateMap()
167				};
168			}
169		};
170	}
