194	/**
195	 * @param {string} str
196	 */
197	export function parseObject(str) {
198		const updated = str
199			.replaceAll(/{(\n\s*)?/gm, '{"')
200			.replaceAll(':', '":')
201			.replaceAll(/,(\n\s*)?([^ ])/g, ',"$2');
202		try {
203			return JSON.parse(updated);
204		} catch {
205			throw new Error(`Failed parsing string to object: ${str}`);
206		}
207	}
