52	/** @type {Record<string,string>} */
53	const fallback = {
54		'.avif': 'png',
55		'.gif': 'gif',
56		'.heif': 'jpg',
57		'.jpeg': 'jpg',
58		'.jpg': 'jpg',
59		'.png': 'png',
60		'.tiff': 'jpg',
61		'.webp': 'png'
62	};
63	
64	function imagetools_plugin() {
65		/** @type {Partial<import('vite-imagetools').VitePluginOptions>} */
66		const imagetools_opts = {
67			defaultDirectives: async ({ pathname, searchParams: qs }, metadata) => {
68				if (!qs.has('enhanced')) return new URLSearchParams();
69	
70				const img_width = qs.get('imgWidth');
71				const width = img_width ? parseInt(img_width) : (await metadata()).width;
72				if (!width) {
73					console.warn(`Could not determine width of image ${pathname}`);
74					return new URLSearchParams();
75				}
76	
77				const { widths, kind } = get_widths(width, qs.get('imgSizes'));
78				return new URLSearchParams({
79					as: 'picture',
80					format: `avif;webp;${fallback[path.extname(pathname)] ?? 'png'}`,
81					w: widths.join(';'),
82					...(kind === 'x' && !qs.has('w') && { basePixels: widths[0].toString() })
83				});
84			},
85			namedExports: false
86		};
87	
88		// TODO: should we make formats or sizes configurable besides just letting people override defaultDirectives?
89		// TODO: generate img rather than picture if only a single format is provided
90		//     by resolving the directives for the URL in the preprocessor
91		return imagetools(imagetools_opts);
92	}
