94	/**
95	 * @param {number} width
96	 * @param {string | null} sizes
97	 * @returns {{ widths: number[]; kind: 'w' | 'x' }}
98	 */
99	function get_widths(width, sizes) {
100		// We don't really know what the user wants here. But if they have an image that's really big
101		// then we can probably assume they're always displaying it full viewport/breakpoint.
102		// If the user is displaying a responsive image then the size usually doesn't change that much
103		// Instead, the number of columns in the design may reduce and the image may take a greater
104		// fraction of the screen.
105		// Assume if they're bothering to specify sizes that it's going to take most of the screen
106		// as that's the case where an image may be rendered at very different sizes. Otherwise, it's
107		// probably a responsive image and a single size is okay (two when accounting for HiDPI).
108		if (sizes) {
109			// Use common device sizes. Doesn't hurt to include larger sizes as the user will rarely
110			// provide an image that large.
111			// https://screensiz.es/
112			// https://gs.statcounter.com/screen-resolution-stats (note: logical. we want physical)
113			// Include 1080 because lighthouse uses a moto g4 with 360 logical pixels and 3x pixel ratio.
114			const widths = [540, 768, 1080, 1366, 1536, 1920, 2560, 3000, 4096, 5120];
115			widths.push(width);
116			return { widths, kind: 'w' };
117		}
118	
119		// Don't need more than 2x resolution. Note that due to this optimization, pixel density
120		// descriptors will often end up being cheaper as many mobile devices have pixel density ratios
121		// near 3 which would cause larger images to be chosen on mobile when using sizes.
122	
123		// Most OLED screens that say they are 3x resolution, are actually 3x in the green color, but
124		// only 1.5x in the red and blue colors. Showing a 3x resolution image in the app vs a 2x
125		// resolution image will be visually the same, though the 3x image takes significantly more
126		// data. Even true 3x resolution screens are wasteful as the human eye cannot see that level of
127		// detail without something like a magnifying glass.
128		// https://blog.twitter.com/engineering/en_us/topics/infrastructure/2019/capping-image-fidelity-on-ultra-high-resolution-devices.html
129		return { widths: [Math.round(width / 2), width], kind: 'x' };
130	}
