11		const processed = await preprocess(
12			await fs.readFile(resolve(filename), { encoding: 'utf-8' }),
13			[
14				image({
15					plugin_context: {
16						// @ts-ignore
17						resolve(url) {
18							return { id: url };
19						}
20					},
21					// @ts-ignore
22					imagetools_plugin: {
23						load(id) {
24							if (id.includes('dev')) {
25								return 'export default {sources:{avif:"/1 1440w, /2 960w",webp:"/3 1440w, /4 960w",png:"5 1440w, /6 960w"},img:{src:"/7",w:1440,h:1440}};';
26							} else if (id.includes('prod')) {
27								return 'export default {sources:{avif:"__VITE_ASSET__2AM7_y_a__ 1440w, __VITE_ASSET__2AM7_y_b__ 960w",webp:"__VITE_ASSET__2AM7_y_c__ 1440w, __VITE_ASSET__2AM7_y_d__ 960w",png:"__VITE_ASSET__2AM7_y_e__ 1440w, __VITE_ASSET__2AM7_y_f__ 960w"},img:{src:"__VITE_ASSET__2AM7_y_g__",w:1440,h:1440}};';
